from datetime import datetime


class Classroom:
    def __init__(self, id):
        self.id = id
        self._courses = []

    @property
    def courses(self):
        return self._courses

    @courses.setter
    def courses(self, courses):
        self._courses = courses

    def add_course(self, course):
        if course not in self._courses:
            self._courses.append(course)

    def remove_course(self, course):
        if course in self._courses:
            self._courses.remove(course)

    @staticmethod
    def _parse_time(time_str):
        return datetime.strptime(time_str, '%H:%M')

    @staticmethod
    def _is_time_in_range(check_time, start_time, end_time):
        return start_time <= check_time <= end_time

    def is_free_at(self, check_time):
        check_time_dt = self._parse_time(check_time)

        for course in self._courses:
            start_time = self._parse_time(course['start_time'])
            end_time = self._parse_time(course['end_time'])
            if self._is_time_in_range(check_time_dt, start_time, end_time):
                return False
        return True

    @staticmethod
    def _has_overlap(start1, end1, start2, end2):
        return (start1 <= end2 and end1 >= start2)

    def check_course_conflict(self, new_course):
        new_start_time = self._parse_time(new_course['start_time'])
        new_end_time = self._parse_time(new_course['end_time'])

        for course in self._courses:
            course_start_time = self._parse_time(course['start_time'])
            course_end_time = self._parse_time(course['end_time'])
            if self._has_overlap(new_start_time, new_end_time, course_start_time, course_end_time):
                return False
        return True
